    // ══════════════════════════════════════════════════════════════
    // CONSISTENCY STUDIO (Explore → Lock → Verify)
    // ══════════════════════════════════════════════════════════════
    let _consistencyData = { characters: [], locations: [], props: [] };
    let _consistencyProfiles = {};   // profile.id -> profile (with .refs)
    let _consistencyAssets = [];     // project assets (for the ref picker)
    // Fallback vocab; overridden at runtime by the API's ref_roles (single source
    // of truth lives in backend consistency-context.js). Order = truncation priority.
    let _consistencyRefRoles = ['canonical', 'face', 'front', 'side', 'back', 'full_body', 'expression', 'wide', 'detail', 'color'];
    const CONSISTENCY_IMG_TYPES = ['character_sheet', 'reference_sheet', 'reference_image', 'storyboard', 'keyframe'];
    function _cParse(s) { try { return JSON.parse(s || '{}'); } catch (_) { return {}; } }

    function switchConsistencyTab(tab) {
        document.querySelectorAll('#consistencyTabs .tab-btn').forEach(b => b.classList.toggle('active', b.dataset.ctab === tab));
        document.getElementById('consistencyCharacters').style.display = tab === 'characters' ? 'grid' : 'none';
        document.getElementById('consistencyLocations').style.display = tab === 'locations' ? 'grid' : 'none';
        document.getElementById('consistencyProps').style.display = tab === 'props' ? 'grid' : 'none';
        document.getElementById('consistencyAudit').style.display = tab === 'audit' ? 'block' : 'none';
        document.getElementById('consistencyVerify').style.display = tab === 'verify' ? 'block' : 'none';
        if (tab === 'verify') loadConsistencyVerify();
    }

    async function loadConsistency() {
        if (!state.currentProject) return;
        const pid = state.currentProject.id;
        setStatus('Loading consistency...');
        try {
            const [charsD, locsD, propsD, profD, assetsD, auditD] = await Promise.all([
                api('/projects/' + pid + '/characters').catch(() => ({ characters: [] })),
                api('/projects/' + pid + '/locations').catch(() => ({ locations: [] })),
                api('/projects/' + pid + '/props').catch(() => ({ props: [] })),
                api('/projects/' + pid + '/consistency/profiles').catch(() => ({ profiles: [] })),
                api('/projects/' + pid + '/assets').catch(() => ({ assets: [] })),
                api('/projects/' + pid + '/consistency/audit').catch(() => ({ ready: true, shots: [] })),
            ]);
            _consistencyData = { characters: charsD.characters || [], locations: locsD.locations || [], props: propsD.props || [] };
            const profiles = profD.profiles || [];
            const assets = assetsD.assets || [];
            _consistencyAssets = assets;
            _consistencyProfiles = {}; profiles.forEach(p => { _consistencyProfiles[p.id] = p; });
            if (Array.isArray(profD.ref_roles) && profD.ref_roles.length) _consistencyRefRoles = profD.ref_roles;
            const profBySubject = {}; profiles.forEach(p => { profBySubject[p.profile_type + ':' + p.subject_id] = p; });
            const IMG_TYPES = CONSISTENCY_IMG_TYPES;
            const refAssetFor = (field, id) => assets.find(a => IMG_TYPES.includes(a.asset_type) && (a[field] === id || _cParse(a.metadata)[field] === id));

            // Readiness banner
            const lockedCount = profiles.filter(p => p.status === 'locked').length;
            const shotsReady = (auditD.shots || []).filter(s => s.ready).length;
            document.getElementById('consistencyReadiness').innerHTML = `<div class="card" style="border-left:4px solid ${auditD.ready ? 'var(--gl-success,#22c55e)' : 'var(--gl-warning,#f59e0b)'};">
                <strong>${auditD.ready ? '✓ Consistency ready' : '⚠ Consistency incomplete'}</strong>
                <span class="text-sm text-muted"> — ${lockedCount} profile(s) locked${(auditD.shots && auditD.shots.length) ? ', ' + shotsReady + '/' + auditD.shots.length + ' shots ready' : ''}.</span>
                ${(auditD.warnings && auditD.warnings.length) ? '<div class="text-sm text-muted" style="margin-top:6px;">' + auditD.warnings.map(esc).join(' · ') + '</div>' : ''}
            </div>`;

            renderConsistencySubjects('consistencyCharacters', 'character', _consistencyData.characters, 'character_id', profBySubject, refAssetFor);
            renderConsistencySubjects('consistencyLocations', 'location', _consistencyData.locations, 'location_id', profBySubject, refAssetFor);
            renderConsistencySubjects('consistencyProps', 'prop', _consistencyData.props, 'prop_id', profBySubject, refAssetFor);
            renderConsistencyAudit(auditD);
            setStatus('Consistency: ' + lockedCount + ' locked');
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    function renderConsistencySubjects(elId, type, subjects, idField, profBySubject, refAssetFor) {
        const el = document.getElementById(elId);
        if (!subjects.length) { el.innerHTML = '<div class="empty-state" style="grid-column:1/-1;"><div class="icon">&#128274;</div><h3>No ' + type + 's</h3><p>Create ' + type + 's first, then lock a canonical reference.</p></div>'; return; }
        el.innerHTML = subjects.map(s => {
            const prof = profBySubject[type + ':' + s.id];
            const refAsset = refAssetFor(idField, s.id);
            const thumb = s.reference_image_url;
            const locked = prof && prof.status === 'locked';
            const status = locked ? '<span class="tag" style="background:var(--gl-success,#166534);">&#128274; locked</span>'
                : prof ? '<span class="tag">draft</span>' : '<span class="tag">not locked</span>';
            const action = locked
                ? '<button class="btn btn-secondary btn-sm" onclick="unlockConsistency(\'' + prof.id + '\')">Unlock</button>'
                : refAsset
                    ? '<button class="btn btn-primary btn-sm" onclick="lockConsistency(\'' + type + '\',\'' + s.id + '\',\'' + refAsset.id + '\')">Lock for production</button>'
                    : '<button class="btn btn-secondary btn-sm" disabled title="Generate a reference image/sheet first">Lock (needs reference)</button>';
            return `<div class="entity-card">
                <div class="flex-between"><strong style="font-size:13px;">${esc(s.name)}</strong>${status}</div>
                ${thumb ? '<img src="' + API_BASE + esc(thumb) + '" style="width:100%;border-radius:6px;margin-top:8px;max-height:200px;object-fit:cover;" onerror="this.style.display=\'none\'">' : '<p class="text-sm text-muted" style="margin-top:8px;">No reference image yet — generate a reference image on the ' + (type === 'character' ? 'Characters' : type === 'prop' ? 'Props' : 'Locations') + ' page to explore, then lock one here.</p>'}
                <div style="margin-top:8px;">${action}</div>
                ${renderRefManager(prof, type, s)}
                ${type === 'character' ? renderVoiceRow(s, profBySubject['voice:' + s.id]) : ''}
            </div>`;
        }).join('');
    }

    function renderVoiceRow(char, voiceProf) {
        const locked = voiceProf && voiceProf.status === 'locked';
        const hasVoice = !!char.voice_profile_id;
        const badge = locked ? '<span class="tag" style="background:var(--gl-success,#166534);">&#128274; voice</span>'
            : hasVoice ? '<span class="tag">voice not locked</span>' : '<span class="tag">no voice profile</span>';
        const btn = locked
            ? '<button class="btn btn-secondary btn-sm" onclick="unlockConsistency(\'' + voiceProf.id + '\')">Unlock</button>'
            : hasVoice
                ? '<button class="btn btn-secondary btn-sm" onclick="lockVoice(\'' + char.id + '\')">Lock voice</button>'
                : '<button class="btn btn-secondary btn-sm" disabled title="Set a voice profile on the character first">Lock voice</button>';
        return '<div style="margin-top:6px;border-top:1px solid var(--gl-border-subtle);padding-top:6px;display:flex;gap:6px;flex-wrap:wrap;justify-content:space-between;align-items:center;"><span class="text-sm">Voice ' + badge + '</span>' + btn + '</div>';
    }

    // Multi-reference role management. A profile can hold several role-tagged
    // references (front / side / back / expression / face / full_body) beyond the
    // single canonical image — the largest per-shot consistency gain, and the
    // reference set the generator side passes through as image[] / input_refs.
    // Voice profiles have no visual references, so this is skipped for them.
    function renderRefManager(prof, type, subject) {
        if (type === 'voice') return '';
        if (!prof) {
            return '<div style="margin-top:8px;border-top:1px solid var(--gl-border-subtle);padding-top:8px;">'
                + '<button class="btn btn-secondary btn-sm" onclick="startProfileForRefs(\'' + type + '\',\'' + subject.id + '\')">+ Add reference roles</button>'
                + '<div class="text-sm text-muted" style="margin-top:4px;">Attach front / side / back / expression / face references for stronger consistency.</div></div>';
        }
        const refs = Array.isArray(prof.refs) ? prof.refs : [];
        const requiredRoles = parseJsonArray(prof.required_roles);
        // Image assets available for this subject (matched by id field or metadata).
        const idField = type === 'character' ? 'character_id' : type === 'location' ? 'location_id' : 'prop_id';
        const candidates = _consistencyAssets.filter(a => CONSISTENCY_IMG_TYPES.includes(a.asset_type)
            && (a[idField] === subject.id || _cParse(a.metadata)[idField] === subject.id));
        const usedAssetIds = new Set(refs.map(r => r.asset_id));
        const options = candidates.filter(a => !usedAssetIds.has(a.id))
            .map(a => '<option value="' + a.id + '">' + esc(a.file_name || a.asset_type || a.id) + '</option>').join('');

        const roleChips = _consistencyRefRoles.map(role => {
            const on = requiredRoles.includes(role);
            return '<button class="tag" style="cursor:pointer;border:1px solid var(--gl-border-subtle);'
                + (on ? 'background:var(--gl-accent,#2563eb);color:#fff;' : 'opacity:0.6;')
                + '" title="Toggle whether this role is required" onclick="toggleRequiredRole(\'' + prof.id + '\',\'' + role + '\')">' + role + '</button>';
        }).join(' ');

        const refRows = refs.length ? refs.map(r => {
            const missing = !r.asset_id;
            const badge = '<span class="tag" style="background:var(--gl-accent-dim,#1e3a5f);">' + esc(r.ref_role) + '</span>';
            const reqStar = r.is_required ? ' <span title="required" style="color:var(--gl-warning,#f59e0b);">★</span>' : '';
            const name = missing ? '<span class="text-muted">(asset removed)</span>' : esc(r.asset_file_name || r.asset_id);
            return '<div style="display:flex;align-items:center;justify-content:space-between;gap:6px;padding:3px 0;">'
                + '<span class="text-sm">' + badge + reqStar + ' ' + name + ' <span class="text-muted">w' + (r.weight != null ? r.weight : '0.7') + '</span></span>'
                + '<button class="btn btn-secondary btn-sm" onclick="removeProfileRef(\'' + r.id + '\')">Remove</button></div>';
        }).join('') : '<div class="text-sm text-muted">Only the canonical reference so far.</div>';

        const addForm = options
            ? '<div style="display:flex;gap:4px;margin-top:6px;flex-wrap:wrap;align-items:center;">'
                + '<select id="refAsset_' + prof.id + '" class="input input-sm" style="flex:1;min-width:120px;">' + options + '</select>'
                + '<select id="refRole_' + prof.id + '" class="input input-sm" style="width:110px;">'
                + _consistencyRefRoles.map(r => '<option value="' + r + '"' + (r === 'front' ? ' selected' : '') + '>' + r + '</option>').join('') + '</select>'
                + '<input id="refWeight_' + prof.id + '" class="input input-sm" style="width:64px;" type="number" step="0.05" min="0" max="1" value="0.7" title="reference weight">'
                + '<button class="btn btn-primary btn-sm" onclick="addProfileRef(\'' + prof.id + '\')">Add</button></div>'
            : '<div class="text-sm text-muted" style="margin-top:6px;">Generate more reference images for this ' + type + ' to attach additional roles.</div>';

        const wt = prof.reference_weight != null ? prof.reference_weight : 0.7;
        const weightRow = '<div style="margin-top:8px;display:flex;align-items:center;gap:6px;">'
            + '<span class="text-sm text-muted">Default reference weight:</span>'
            + '<input id="profWeight_' + prof.id + '" class="input input-sm" style="width:72px;" type="number" step="0.05" min="0" max="1" value="' + wt + '" title="Primary IP-Adapter / reference weight for this subject">'
            + '<button class="btn btn-secondary btn-sm" onclick="setProfileWeight(\'' + prof.id + '\')">Save</button></div>';

        return '<details class="ref-manager" style="margin-top:8px;border-top:1px solid var(--gl-border-subtle);padding-top:8px;">'
            + '<summary style="cursor:pointer;font-size:12px;">References (' + refs.length + ') &middot; weight ' + wt + ' &middot; required roles</summary>'
            + '<div style="margin-top:6px;"><div class="text-sm text-muted" style="margin-bottom:4px;">Required roles (click to toggle):</div>'
            + '<div style="display:flex;flex-wrap:wrap;gap:4px;">' + roleChips + '</div>'
            + weightRow
            + '<div style="margin-top:8px;">' + refRows + '</div>'
            + addForm + '</div></details>';
    }

    // Create a draft profile so references can be attached before locking.
    // Name is looked up from state (never passed through the inline handler) so a
    // subject name containing a quote can't break or inject into the onclick.
    async function startProfileForRefs(type, subjectId) {
        const list = type === 'character' ? _consistencyData.characters
            : type === 'prop' ? _consistencyData.props
            : _consistencyData.locations;
        const subj = (list || []).find(x => x.id === subjectId) || {};
        const name = subj.name || subjectId;
        try {
            await api('/projects/' + state.currentProject.id + '/consistency/profiles', {
                method: 'POST', body: JSON.stringify({ profile_type: type, subject_id: subjectId, subject_name: name }),
            });
            setStatus('Draft profile ready — attach references');
            loadConsistency();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function addProfileRef(profileId) {
        const asset = document.getElementById('refAsset_' + profileId);
        const role = document.getElementById('refRole_' + profileId);
        const weightEl = document.getElementById('refWeight_' + profileId);
        if (!asset || !asset.value) { setStatus('Pick a reference asset first'); return; }
        const weight = parseFloat(weightEl && weightEl.value);
        try {
            await api('/consistency/profiles/' + profileId + '/refs', {
                method: 'POST',
                body: JSON.stringify({ asset_id: asset.value, ref_role: role ? role.value : 'front', weight: Number.isFinite(weight) ? weight : 0.7 }),
            });
            setStatus('Reference added');
            loadConsistency();
        } catch (err) { setStatus('Add reference error: ' + err.message); }
    }

    async function removeProfileRef(refId) {
        try {
            await api('/consistency/refs/' + refId, { method: 'DELETE' });
            setStatus('Reference removed');
            loadConsistency();
        } catch (err) { setStatus('Remove error: ' + err.message); }
    }

    async function setProfileWeight(profileId) {
        const el = document.getElementById('profWeight_' + profileId);
        const w = parseFloat(el && el.value);
        if (!Number.isFinite(w) || w < 0 || w > 1) { setStatus('Weight must be 0–1'); return; }
        try {
            await api('/consistency/profiles/' + profileId, { method: 'PUT', body: JSON.stringify({ reference_weight: w }) });
            setStatus('Reference weight saved');
            loadConsistency();
        } catch (err) { setStatus('Update error: ' + err.message); }
    }

    async function toggleRequiredRole(profileId, role) {
        const prof = _consistencyProfiles[profileId];
        if (!prof) return;
        const roles = parseJsonArray(prof.required_roles);
        const next = roles.includes(role) ? roles.filter(r => r !== role) : roles.concat(role);
        try {
            await api('/consistency/profiles/' + profileId, { method: 'PUT', body: JSON.stringify({ required_roles: next }) });
            prof.required_roles = next; // optimistic
            loadConsistency();
        } catch (err) { setStatus('Update error: ' + err.message); }
    }

    function renderConsistencyAudit(audit) {
        const el = document.getElementById('consistencyAudit');
        const shots = audit.shots || [];
        if (!shots.length) { el.innerHTML = '<p class="text-sm text-muted">No shots to audit yet.</p>'; return; }
        el.innerHTML = '<table class="render-table"><tr><th>Shot</th><th>Ready</th><th>Missing / Warnings</th></tr>' +
            shots.map(s => `<tr>
                <td>${esc(s.shot_code || s.shot_id)}</td>
                <td>${s.ready ? '<span class="tag" style="background:var(--gl-success,#166534);">ready</span>' : '<span class="tag" style="background:var(--gl-danger,#7f1d1d);">not ready</span>'}</td>
                <td class="text-sm">${[...(s.missing || []), ...(s.warnings || [])].map(esc).join(', ') || '—'}</td>
            </tr>`).join('') + '</table>';
    }

    async function lockConsistency(type, subjectId, assetId) {
        const list = type === 'character' ? _consistencyData.characters
            : type === 'prop' ? _consistencyData.props
            : _consistencyData.locations;
        const subj = (list || []).find(x => x.id === subjectId) || {};
        const name = subj.name || subjectId;
        // Prefill the prompt contract from the subject's own descriptive fields so
        // a locked profile carries BOTH the image anchor and the text contract.
        const promptContract = type === 'character' ? (subj.appearance_prompt || subj.description || '')
            : type === 'prop' ? (subj.visual_prompt || subj.description || '')
            : (subj.reference_prompt || subj.description || '');
        try {
            const prof = await api('/projects/' + state.currentProject.id + '/consistency/profiles', {
                method: 'POST', body: JSON.stringify({ profile_type: type, subject_id: subjectId, subject_name: name, canonical_asset_id: assetId, prompt_contract: promptContract }),
            });
            // Ensure the contract is applied even if the profile already existed.
            if (promptContract && !prof.prompt_contract) {
                await api('/consistency/profiles/' + prof.id, { method: 'PUT', body: JSON.stringify({ prompt_contract: promptContract, canonical_asset_id: assetId }) });
            }
            await api('/consistency/profiles/' + prof.id + '/lock', { method: 'POST', body: '{}' });
            setStatus(name + ' locked for production');
            loadConsistency();
        } catch (err) { setStatus('Lock error: ' + err.message); }
    }

    // Lock a character's voice (snapshot their voice profile into a 'voice' consistency profile).
    async function lockVoice(subjectId) {
        const subj = (_consistencyData.characters || []).find(x => x.id === subjectId) || {};
        if (!subj.voice_profile_id) { setStatus('No voice profile — set one on the character first'); return; }
        try {
            const prof = await api('/projects/' + state.currentProject.id + '/consistency/profiles', {
                method: 'POST',
                body: JSON.stringify({ profile_type: 'voice', subject_id: subjectId, subject_name: subj.name || subjectId, settings: { voice_profile_id: subj.voice_profile_id } }),
            });
            await api('/consistency/profiles/' + prof.id + '/lock', { method: 'POST', body: '{}' });
            setStatus((subj.name || 'Character') + ' voice locked');
            loadConsistency();
        } catch (err) { setStatus('Voice lock error: ' + err.message); }
    }

    async function unlockConsistency(profileId) {
        try {
            await api('/consistency/profiles/' + profileId + '/unlock', { method: 'POST', body: '{}' });
            setStatus('Unlocked');
            loadConsistency();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    // ── Verify view ────────────────────────────────────────────────
    // Reads persisted consistency checks (the "Verify" corner of
    // Explore→Lock→Generate→Verify). The generator side scores generated
    // output against locked references and writes rows; this view surfaces them.
    const VERIFY_STATUS_COLOR = { ready: 'var(--gl-success,#166534)', warning: 'var(--gl-warning,#92400e)', blocked: 'var(--gl-danger,#7f1d1d)' };

    async function loadConsistencyVerify() {
        const el = document.getElementById('consistencyVerify');
        if (!state.currentProject) { el.innerHTML = '<p class="text-sm text-muted">No project selected.</p>'; return; }
        el.innerHTML = '<p class="text-sm text-muted">Loading verification history…</p>';
        try {
            const data = await api('/projects/' + state.currentProject.id + '/consistency/checks?limit=100');
            renderConsistencyVerify(data);
        } catch (err) {
            el.innerHTML = '<p class="text-sm text-muted">Could not load verification checks: ' + esc(err.message) + '</p>';
        }
    }

    function renderConsistencyVerify(data) {
        const el = document.getElementById('consistencyVerify');
        const checks = (data && data.checks) || [];
        const counts = (data && data.counts) || {};
        if (!checks.length) {
            el.innerHTML = '<div class="empty-state"><div class="icon">&#128269;</div><h3>No verification runs yet</h3>'
                + '<p>Verify measures whether generated output came back on-model. Once a shot is generated with locked references, its output is scored against the canonical reference and recorded here — flagging anything that drifted.</p></div>';
            return;
        }
        const shotName = id => {
            const s = (state.shots || []).find(x => x.id === id);
            return s ? (s.shot_code || s.name || id) : (id ? id.slice(0, 8) : '—');
        };
        const summary = '<div class="card" style="margin-bottom:12px;display:flex;gap:16px;align-items:center;">'
            + '<strong>Verification</strong>'
            + '<span class="tag" style="background:' + VERIFY_STATUS_COLOR.ready + ';">' + (counts.ready || 0) + ' ready</span>'
            + '<span class="tag" style="background:' + VERIFY_STATUS_COLOR.warning + ';">' + (counts.warning || 0) + ' warning</span>'
            + '<span class="tag" style="background:' + VERIFY_STATUS_COLOR.blocked + ';">' + (counts.blocked || 0) + ' blocked</span>'
            + '<span class="text-sm text-muted">' + checks.length + ' recent check(s)</span></div>';

        const rows = checks.map(c => {
            const details = c.details || {};
            const subjects = Array.isArray(details.subjects) ? details.subjects : [];
            const scorer = details.scorer ? '<span class="text-muted"> · ' + esc(details.scorer) + '</span>' : '';
            const subjHtml = subjects.length ? subjects.map(renderVerifySubject).join('') : '<span class="text-sm text-muted">No per-subject scores.</span>';
            const notes = [...(c.missing || []), ...(c.warnings || [])];
            const notesHtml = notes.length ? '<div class="text-sm text-muted" style="margin-top:4px;">' + notes.map(esc).join(' · ') + '</div>' : '';
            return '<tr><td>' + esc(shotName(c.shot_id)) + '</td>'
                + '<td><span class="tag" style="background:' + (VERIFY_STATUS_COLOR[c.status] || '#555') + ';">' + esc(c.status) + '</span>' + scorer + '</td>'
                + '<td>' + subjHtml + notesHtml + '</td>'
                + '<td class="text-sm text-muted">' + esc((c.created_at || '').replace('T', ' ').slice(0, 16)) + '</td></tr>';
        }).join('');

        el.innerHTML = summary + '<table class="render-table"><tr><th>Shot</th><th>Status</th><th>Subjects / notes</th><th>When</th></tr>' + rows + '</table>';
    }

    function renderVerifySubject(s) {
        const name = esc(s.subject_name || s.subject || s.profile_id || 'subject');
        const role = s.role ? ' <span class="text-muted">(' + esc(s.role) + ')</span>' : '';
        const score = typeof s.score === 'number' ? s.score : null;
        const st = s.status || (score == null ? '' : score >= 0.85 ? 'ready' : score >= 0.70 ? 'warning' : 'blocked');
        const color = VERIFY_STATUS_COLOR[st] || '#888';
        const pct = score == null ? 0 : Math.max(0, Math.min(100, Math.round(score * 100)));
        const bar = score == null ? '<span class="text-muted">no score</span>'
            : '<span style="display:inline-block;width:80px;height:8px;border-radius:4px;background:var(--gl-border-subtle,#333);vertical-align:middle;overflow:hidden;">'
                + '<span style="display:block;height:100%;width:' + pct + '%;background:' + color + ';"></span></span>'
                + ' <span class="text-sm">' + pct + '%</span>';
        return '<div style="display:flex;align-items:center;gap:6px;padding:2px 0;"><span class="text-sm" style="min-width:120px;">' + name + role + '</span>' + bar + '</div>';
    }
